const JOB_SUMMARY_NODE = 'Read Job Summary for Daily Report';
const OPERATIVE_SHEET_NODE = 'Attach Access Classification';
// Disable only if EasyBOP confirms Q2.8 is optional.
const VALIDATE_OUTSTANDING_WORKS = true;

const FIELDS = {
  address: 'Q1.1 Address',
  date: 'Q1.2 Date',
  jobDetails: 'Q1.3 Job details',
  asbestos:
    'Q1.4 Have you read and understood the asbestos report for the property or checked the status with a Manager or Supervisor before',
  dailyJobs: 'Q2.1 Daily Jobs Table',
  dailyHours: 'Q2.1 Daily Jobs Table Price/Hours',
  completedInFull:
    'Q2.2 Were you able to complete your work in full?',
  completedPhotos:
    'Q2.3 Please provide photos of completed work',
  variations:
    'Q2.4 Did you complete any additonal work or variations?',
  incompleteReason:
    'Q2.5 Please explain why you could not complete your job',
  variationPhotos:
    'Q2.6 Please provide photos of variations',
  variationDetails:
    'Q2.7 Please provide some detail on the variations? Task, QTY, Location. e.g. skimmed extra 3 sqm in lounge.',
  outstandingWorks:
    'Q2.8 Please provide details of any outstanding works you are aware of for this property',
  notes: 'Q3.1 Notes, if applicable',
  employeeName: 'Q4.1 Employee Name',
  employeeSignature: 'Q4.2 Employee Signature',
};

function clean(value) {
  return value === null || value === undefined
    ? ''
    : String(value).trim();
}

function normalized(value) {
  return clean(value).toLowerCase();
}

function isMissing(value) {
  const result = normalized(value);

  return result === '' || result === 'not answered';
}

function isNotAnswered(value) {
  return normalized(value) === 'not answered';
}

function hasValue(value) {
  return !isMissing(value);
}

function flattenItems(items) {
  const rows = [];

  for (const item of items) {
    const json = item.json;

    if (Array.isArray(json)) {
      rows.push(...json);
    } else if (Array.isArray(json?.data)) {
      rows.push(...json.data);
    } else if (Array.isArray(json?.rows)) {
      rows.push(...json.rows);
    } else if (json && typeof json === 'object') {
      rows.push(json);
    }
  }

  return rows.filter(
    row => row && typeof row === 'object',
  );
}

function getOptionalNodeRows(nodeName) {
  try {
    return flattenItems($(nodeName).all());
  } catch {
    return [];
  }
}

function getRequiredNodeRows(nodeName) {
  let items;

  try {
    items = $(nodeName).all();
  } catch {
    throw new Error(
      `Cannot read required node "${nodeName}".`,
    );
  }

  const rows = flattenItems(items);

  if (rows.length === 0) {
    throw new Error(
      `Required node "${nodeName}" returned no rows.`,
    );
  }

  return rows;
}

function extractCorf(row) {
  const direct =
    clean(row.CORF) ||
    clean(row.corf) ||
    clean(row['CORF Number']);

  if (direct) {
    return direct;
  }

  const source =
    clean(row['SmartForm Name']) ||
    clean(row['Job Header']) ||
    clean(row['Job Summary']);

  return source.match(/:\s*(\d+)\s*$/)?.[1] || '';
}

function extractFirstDate(value) {
  return clean(value).match(
    /\d{2}\/\d{2}\/\d{4}/,
  )?.[0] || '';
}

function isTruthyFlag(value) {
  return [
    'true',
    'yes',
    '1',
    'access issue',
    'access issue detected',
  ].includes(normalized(value));
}

function getAccessIssue(row) {
  const explicitValue =
    row['Access Issue'] ??
    row['Access Issue Detected'] ??
    row['Has Access Issue'] ??
    row.access_issue;

  if (
    explicitValue !== null &&
    explicitValue !== undefined &&
    clean(explicitValue) !== ''
  ) {
    return isTruthyFlag(explicitValue);
  }

  // Fallback: detect the exact marker written into notes by OpenAI.
  return normalized(row[FIELDS.notes]).includes(
    'access issue',
  );
}

function dateTimestamp(value) {
  const date = extractFirstDate(value);
  const match = date.match(
    /^(\d{2})\/(\d{2})\/(\d{4})$/,
  );

  if (!match) {
    return 0;
  }

  const [, day, month, year] = match;

  return Date.UTC(
    Number(year),
    Number(month) - 1,
    Number(day),
  );
}

function formKey(row) {
  return (
    clean(row.smart_form_x_id) ||
    [
      extractCorf(row),
      extractFirstDate(row[FIELDS.date]),
      clean(row[FIELDS.employeeName]),
      clean(row['SmartForm Name']),
    ].join('|')
  );
}

function jobKey(row) {
  return (
    extractCorf(row) ||
    clean(row['Job Header']) ||
    clean(row['SmartForm Name']) ||
    clean(row['Job Summary'])
  );
}

function uniqueRows(rows, keyFunction) {
  const seen = new Set();
  const result = [];

  for (const row of rows) {
    const key = keyFunction(row);

    if (!key || seen.has(key)) {
      continue;
    }

    seen.add(key);
    result.push(row);
  }

  return result;
}

function baseRecord(row) {
  return {
    smart_form_name:
      clean(row['SmartForm Name']) ||
      clean(row['Job Header']) ||
      clean(row['Job Summary']),

    corf: extractCorf(row),

    operative:
      clean(row[FIELDS.employeeName]) ||
      clean(row['Created By']) ||
      clean(row.Operative),

    form_date:
      extractFirstDate(row[FIELDS.date]) ||
      extractFirstDate(row['Date Created']) ||
      extractFirstDate(row.Date),

    date_created:
      extractFirstDate(row['Date Created']) ||
      extractFirstDate(row[FIELDS.date]),

    smart_form_x_id: clean(row.smart_form_x_id),
    pdf_url: clean(row.pdf_url),
    job_status: normalized(row['Job Status']),

    notes: isMissing(row[FIELDS.notes])
      ? ''
      : clean(row[FIELDS.notes]),

    access_issue: getAccessIssue(row),

    access_issue_reason: clean(row.access_issue_reason),
  };
}

const jobSummaryRows = uniqueRows(
  getOptionalNodeRows(JOB_SUMMARY_NODE),
  jobKey,
);

const operativeRows = uniqueRows(
  getOptionalNodeRows(OPERATIVE_SHEET_NODE).filter(row => !row._no_rows_in_scope),
  formKey,
);

/*
 * Index operative forms by CORF so Section 1 can include
 * a link to the latest available operative form.
 */
const operativeFormsByCorf = new Map();

for (const row of operativeRows) {
  const corf = extractCorf(row);

  if (!corf) {
    continue;
  }

  if (!operativeFormsByCorf.has(corf)) {
    operativeFormsByCorf.set(corf, []);
  }

  operativeFormsByCorf.get(corf).push(row);
}

for (const forms of operativeFormsByCorf.values()) {
  forms.sort((a, b) => {
    return dateTimestamp(
      b[FIELDS.date] || b['Date Created'],
    ) - dateTimestamp(
      a[FIELDS.date] || a['Date Created'],
    );
  });
}

/*
 * Condition 1:
 * Job Summary rows where Job Status = incomplete.
 */
const nextAppointments = jobSummaryRows
  .filter(row =>
    normalized(row['Job Status']) === 'incomplete',
  )
  .map(row => {
    const record = baseRecord(row);
    const matchingForms =
  operativeFormsByCorf.get(record.corf) || [];

  const matchingForm = matchingForms[0];

  const accessForm = matchingForms.find(
    form => form.access_issue === true,
  );

    if (matchingForm) {
      record.smart_form_x_id =
        clean(matchingForm.smart_form_x_id);

      record.pdf_url =
        clean(matchingForm.pdf_url);

      record.notes = isMissing(
        matchingForm[FIELDS.notes],
      )
        ? ''
        : clean(matchingForm[FIELDS.notes]);

      record.access_issue = Boolean(accessForm);

      record.access_issue_reason = accessForm
        ? clean(accessForm.access_issue_reason)
        : '';

      if (!record.form_date) {
        record.form_date =
          extractFirstDate(matchingForm[FIELDS.date]) ||
          extractFirstDate(
            matchingForm['Date Created'],
          );
      }
    }

    return {
      ...record,
      reason:
        clean(row['Job Status Notes']) ||
        clean(row.Reason) ||
        'Job marked incomplete',
    };
  })
  .sort((a, b) =>
    a.smart_form_name.localeCompare(
      b.smart_form_name,
      undefined,
      { numeric: true },
    ),
  );

/*
 * Condition 2:
 * Validate each Operative Job Sheet form.
 */
const incorrectForms = [];

for (const row of operativeRows) {
  const issues = [];

  const requiredFields = [
    [FIELDS.address, 'Address missing'],
    [FIELDS.date, 'Form date missing'],
    [FIELDS.jobDetails, 'Job details missing'],
    [FIELDS.asbestos, 'Asbestos confirmation missing'],
    [FIELDS.dailyJobs, 'Daily Jobs description missing'],
    [FIELDS.dailyHours, 'Daily Jobs hours missing'],
    [
      FIELDS.completedInFull,
      'Work completed in full answer missing',
    ],
    [
      FIELDS.variations,
      'Additional work/variation answer missing',
    ],
    [FIELDS.employeeName, 'Employee name missing'],
  ];

  for (const [field, message] of requiredFields) {
    if (isMissing(row[field])) {
      issues.push(message);
    }
  }

  const completedAnswer = normalized(
    row[FIELDS.completedInFull],
  );

  const variationAnswer = normalized(
    row[FIELDS.variations],
  );

  if (
    completedAnswer === 'no' &&
    isMissing(row[FIELDS.incompleteReason])
  ) {
    issues.push(
      'Reason job was not completed is missing',
    );
  }

  if (
    VALIDATE_OUTSTANDING_WORKS &&
    completedAnswer === 'no' &&
    isMissing(row[FIELDS.outstandingWorks])
  ) {
    issues.push(
      'Outstanding works details are missing',
    );
  }

  if (
    variationAnswer === 'yes' &&
    isMissing(row[FIELDS.variationDetails])
  ) {
    issues.push('Variation details are missing');
  }

  if (issues.length > 0) {
    incorrectForms.push({
      ...baseRecord(row),
      issues,
      issue_summary: issues.join('; '),
    });
  }
}

/*
 * Condition 3:
 * Only literal "Not Answered" photo values are missing.
 */
const missingPhotos = [];

for (const row of operativeRows) {
  const issues = [];

  const dailyJobsContainWork = hasValue(
    row[FIELDS.dailyJobs],
  );

  const variationAnswer = normalized(
    row[FIELDS.variations],
  );

  if (
    dailyJobsContainWork &&
    isNotAnswered(row[FIELDS.completedPhotos])
  ) {
    issues.push('Completed-work photos missing');
  }

  if (
    variationAnswer === 'yes' &&
    isNotAnswered(row[FIELDS.variationPhotos])
  ) {
    issues.push('Variation photos missing');
  }

  if (issues.length > 0) {
    missingPhotos.push({
      ...baseRecord(row),
      issues,
      issue_summary: issues.join('; '),
    });
  }
}

return [
  {
    json: {
      report_generated_at: new Date().toISOString(),

      summary: {
        next_appointment_jobs:
          nextAppointments.length,
        incorrectly_completed_forms:
          incorrectForms.length,
        forms_missing_photos:
          missingPhotos.length,
        operative_rows_in_scope:
          operativeRows.length,
      },

      operative_rows_in_scope: operativeRows.length,
      next_appointments: nextAppointments,
      incorrect_forms: incorrectForms,
      missing_photos: missingPhotos,

      total_exception_count:
        nextAppointments.length +
        incorrectForms.length +
        missingPhotos.length,
    },
  },
];

