function extractApiBody(resp) {
  const statusCode = resp.statusCode ?? resp.status ?? 0;
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (e) {
      const m = body.match(/\{[\s\S]*\}/);
      if (m) {
        try { body = JSON.parse(m[0]); } catch (e2) { body = {}; }
      } else {
        body = {};
      }
    }
  }
  if (
    body &&
    typeof body === 'object' &&
    body.body &&
    body.results === undefined &&
    body.total_extracted === undefined
  ) {
    body = body.body;
  }
  return { statusCode, body: body || {} };
}

function clean(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}

function isBccResponseRepairsName(name) {
  return /:\s*BCC\s+Respon(?:se|sive)\s+Repairs\b/i.test(String(name || '').trim());
}

const Q21_DESC_COL = 'Q2.1 Daily Jobs Table';
const Q21_PRICE_COL = 'Q2.1 Daily Jobs Table Price/Hours';

function addLabeledFields(target, parsed) {
  const labeled = parsed.labeled_fields || {};
  for (const [col, val] of Object.entries(labeled)) {
    if (val == null) continue;
    if (Array.isArray(val) || (typeof val === 'object' && val !== null)) {
      const text = JSON.stringify(val);
      if (text && text !== '[]' && text !== '{}') target[col] = text;
      continue;
    }
    const text = String(val).trim();
    if (col === Q21_PRICE_COL || text) target[col] = text;
  }
}

// Photos: 'Not Answered' when none attached (so missing-photo validation fires),
// 'Yes' when the operative attached at least one.
function photoValue(parsed, key) {
  const photos = parsed.photos || {};
  const count = Array.isArray(photos[key]) ? photos[key].length : 0;
  return count > 0 ? 'Yes' : 'Not Answered';
}

function corfFromQ11Address(addr) {
  const s = String(addr ?? '').trim();
  const m = s.match(/-(\d+\/\d+)\s*$/);
  return m ? m[1] : '';
}

const respRaw = $('Fetch OJS From EasyBOP').first().json || {};
const { statusCode, body } = extractApiBody(respRaw);
const results = Array.isArray(body.results) ? body.results : [];

const out = [];
for (const r of results) {
  const grid = r.grid || {};
  const cells = grid.cells || {};
  const parsed = r.parsed || {};

  const smartFormName = grid.form_name || cells.list_form_name || parsed.job_header || '';
  if (!isBccResponseRepairsName(smartFormName)) continue;

  const row = {
    smart_form_x_id: clean(r.smart_form_x_id),
    'SmartForm Name': clean(smartFormName),
    'Date Created': clean(grid.date_created || cells.list_date_created),
    'SmartForm Template Name': clean(grid.template_name || cells.list_template_name || parsed.template_title),
    Status: clean(grid.status || cells.list_status || 'Complete'),
    'Completed Date': clean(grid.date_completed || cells.list_date_completed),
    'Completed Time': clean(grid.time_completed || cells.list_time_completed),
    'Created By': clean(grid.created_by || cells.list_created_by),
    Module: clean(grid.module_name || cells.list_module_name),
    CORF: '',
    'Job Header': clean(parsed.job_header),
    pdf_url: clean(r.pdf_url),
    extracted_at: new Date().toISOString(),
  };

  addLabeledFields(row, parsed);
  row['Q2.3 Please provide photos of completed work'] = photoValue(parsed, 'completed_work');
  row['Q2.6 Please provide photos of variations'] = photoValue(parsed, 'variations');
  row.CORF = corfFromQ11Address(row['Q1.1 Address']) || clean(parsed.corf);

  out.push({ json: row });
}

if (!out.length) {
  return [{
    json: {
      _no_rows_in_scope: true,
      _fetch_status: statusCode,
      _fetch_message: body.message || (statusCode >= 400
        ? `extract HTTP ${statusCode}`
        : 'No Complete OJS forms in scope'),
      total_extracted: body.total_extracted ?? 0,
      total_grid_matched: body.total_grid_matched ?? 0,
      total_skipped_part_complete: body.total_skipped_part_complete ?? 0,
      total_skipped_out_of_scope: body.total_skipped_out_of_scope ?? 0,
    },
  }];
}

return out;

const payload =
  $('Build Daily Form Issue Cases').first().json;

return [
  {
    json: {
      report_type: payload.report_type,
      report_generated_at: payload.report_generated_at,
      report_date: payload.report_date,
      summary: payload.summary,
      operative_groups: payload.operative_groups,
      pdf_filename: payload.pdf_filename,
    },
  },
];

function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
}

function statCard(value, label, accent) {
  const color = accent ? 'color:' + accent + ';' : '';
  return '<td style="background:#f7fafb;border:1px solid #dce3e8;border-radius:8px;padding:14px;text-align:center;width:16%;">'
    + '<div style="font-size:22px;font-weight:700;' + color + '">' + escapeHtml(value) + '</div>'
    + '<div style="font-size:10px;color:#56616b;text-transform:uppercase;">' + escapeHtml(label) + '</div></td>';
}

const payload = $('Build Daily PDF Payload').first().json;
const response = $input.first();
const pdf = response.binary?.report_pdf;
if (!pdf) throw new Error('Daily form report PDF was not returned by the API.');

const reportDate = new Date().toLocaleString('en-GB', { timeZone: 'Europe/London' }).replace(',', '');
const logo = 'https://jeffway.co.uk/wp-content/uploads/2025/05/jeffway-group-1.svg';
const sheetUrl = 'https://docs.google.com/spreadsheets/d/1mkklLpvi8klaN4Zo4D_cBrb95PGQ4NbUvtTAvLI4CII/edit';
const s = payload.summary || {};

const statsRow = '<table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:20px;"><tr>'
  + statCard(s.new_issue_count, 'New today', '#145c63')
  + '<td width="6"></td>'
  + statCard(s.existing_open_count || 0, 'Still open', '#56616b')
  + '<td width="6"></td>'
  + statCard(s.total_issue_count || s.new_issue_count, 'Total in PDF', '#145c63')
  + '<td width="6"></td>'
  + statCard(s.affected_operatives, 'Operatives', null)
  + '<td width="6"></td>'
  + statCard(s.access_issue_forms, 'Access issues', '#b23c17')
  + '</tr></table>';

const html = [
  '<!DOCTYPE html><html><head><meta charset="UTF-8"></head>',
  '<body style="margin:0;padding:0;font-family:Arial,Helvetica,sans-serif;background:#f4f4f4;">',
  '<table width="100%" style="background:#f4f4f4;padding:20px;"><tr><td align="center">',
  '<table width="640" style="background:#fff;border-radius:8px;overflow:hidden;">',
  '<tr><td style="background:#145c63;padding:20px;text-align:center;"><img src="' + logo + '" style="max-width:160px;" alt="Jeffway Group"></td></tr>',
  '<tr><td style="padding:24px 24px 8px;"><h2 style="margin:0;color:#145c63;">Daily Form Quality Report</h2>',
  '<p style="color:#56616b;font-size:13px;margin:8px 0 0;">Report date: <strong style="color:#17212b;">' + escapeHtml(payload.report_date) + '</strong> · Generated ' + escapeHtml(reportDate) + ' (Europe/London)</p></td></tr>',
  '<tr><td style="padding:8px 24px 8px;"><p style="color:#444;font-size:14px;margin:0 0 16px;">The daily form quality report is attached as a PDF. Summary:</p>',
  statsRow,
  '</td></tr>',
  '<tr><td style="padding:0 24px 24px;text-align:center;">',
  '<a href="' + sheetUrl + '" style="display:inline-block;padding:10px 18px;background:#145c63;color:#fff;text-decoration:none;border-radius:4px;font-size:13px;">Open Form Issue Cases sheet</a>',
  '</td></tr>',
  '<tr><td style="background:#f7fafb;padding:16px;text-align:center;font-size:11px;color:#56616b;">Jeffway Group · Stage 6 daily form quality automation</td></tr>',
  '</table></td></tr></table></body></html>',
].join('');

return [{
  json: {
    email_subject: 'Daily Form Report — ' + payload.report_date,
    email_html: html,
    new_issue_count: s.new_issue_count,
    existing_open_count: s.existing_open_count || 0,
    total_issue_count: s.total_issue_count || s.new_issue_count,
    affected_operatives: s.affected_operatives,
    affected_forms: s.affected_forms,
    access_issue_forms: s.access_issue_forms,
  },
  binary: {
    report_pdf: {
      ...pdf,
      fileName: payload.pdf_filename,
      mimeType: 'application/pdf',
      fileExtension: 'pdf',
    },
  },
}];

const TZ = 'Europe/London';
const DATE_COL = 'date_created';

function clean(value) {
  return value === null || value === undefined ? '' : String(value).trim();
}

function extractFirstDate(value) {
  return clean(value).match(/\d{2}\/\d{2}\/\d{4}/)?.[0] || '';
}

function londonTodayParts() {
  const fmt = new Intl.DateTimeFormat('en-GB', {
    timeZone: TZ,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  });
  const bits = fmt.formatToParts(new Date());
  const out = {};
  for (const bit of bits) {
    if (bit.type !== 'literal') out[bit.type] = bit.value;
  }
  return { y: +out.year, m: +out.month, d: +out.day };
}

function formatParts(parts) {
  const pad = n => (n < 10 ? '0' + n : String(n));
  return `${pad(parts.d)}/${pad(parts.m)}/${parts.y}`;
}

function addDays(parts, delta) {
  const dt = new Date(Date.UTC(parts.y, parts.m - 1, parts.d));
  dt.setUTCDate(dt.getUTCDate() + delta);
  return { y: dt.getUTCFullYear(), m: dt.getUTCMonth() + 1, d: dt.getUTCDate() };
}

function todayUkDate() {
  return formatParts(londonTodayParts());
}

function readParams() {
  try {
    return $('Set Daily PDF API Params').first().json || {};
  } catch {
    return {};
  }
}

function daysToLookBack() {
  const params = readParams();
  if (params.backfill_all_dates === true) return null;
  const raw = params.days_to_look_back;
  const n = Number(raw);
  if (!Number.isFinite(n) || n < 0) return 0;
  return Math.floor(n);
}

function scopeDateSet() {
  const lookback = daysToLookBack();
  if (lookback === null) return null;
  const dates = new Set();
  const end = londonTodayParts();
  for (let i = 0; i <= lookback; i++) {
    dates.add(formatParts(addDays(end, -i)));
  }
  return dates;
}

const FORM_DATE_COL = 'Q1.2 Date';

function rowDateCreated(row) {
  return (
    extractFirstDate(row.date_created || row[DATE_COL]) ||
    extractFirstDate(row[FORM_DATE_COL] || row.form_date)
  );
}

function dateInScope(dateCreated) {
  const scope = scopeDateSet();
  if (!scope) return true;
  return scope.has(dateCreated);
}

function normalize(value) { return clean(value).toLowerCase(); }

function issueKey(row, issueType) {
  return [row.smart_form_x_id || row.corf, row.date_created || row.form_date, row.operative, issueType]
    .map(value => normalize(value)).join('|');
}

function combineIssues(issues, fallback) {
  const parts = (Array.isArray(issues) && issues.length ? issues : [fallback])
    .map(value => clean(value))
    .filter(Boolean);
  return [...new Set(parts)].join('; ');
}

function isAccessIssue(value) {
  return ['true', 'yes', '1', 'access issue'].includes(normalize(value));
}

function existingRows() {
  try {
    return $('Read Form Issue Cases').all().map(item => item.json || {});
  } catch { return []; }
}

function sheetRowToIssue(row) {
  const issueSummary = clean(
    row.issue_summary || row['Issue Summary'] || row.issue_detail || row['Issue Detail']
  );
  return {
    issue_key: clean(row.issue_key || row['Issue Key']),
    status: clean(row.status || row.Status) || 'Open',
    first_detected_date: extractFirstDate(row.first_detected_date || row['First Detected Date']),
    last_seen_date: extractFirstDate(row.last_seen_date || row['Last Seen Date']),
    resolved_date: extractFirstDate(row.resolved_date || row['Resolved Date']),
    operative: clean(row.operative || row['Created By']) || 'Unknown operative',
    corf: clean(row.corf || row.CORF),
    smart_form_x_id: clean(row.smart_form_x_id || row['SmartForm X ID']),
    form_date: extractFirstDate(row.form_date || row['Date Created'] || row.date_created),
    date_created: extractFirstDate(row.date_created || row['Date Created'] || row.form_date),
    smart_form_name: clean(
      row.smart_form_name || row['SmartForm Name'] || row['SmartForm Template Name']
    ),
    issue_type: clean(row.issue_type || row['Issue Type']),
    issue_detail: clean(row.issue_detail || row['Issue Detail'] || issueSummary),
    issue_summary: issueSummary,
    issue_resolved: clean(row.issue_resolved || row['Issue Resolved']),
    pdf_url: clean(row.pdf_url),
    access_issue: isAccessIssue(row.access_issue || row['Access Issue']),
    access_issue_reason: clean(row.access_issue_reason || row['Access Issue Reason']),
    is_new: false,
  };
}

function buildOperativeGroups(issues) {
  const groupsByOperative = new Map();
  const seenKeys = new Set();
  for (const issue of issues) {
    const nk = normalize(issue.issue_key);
    if (!nk || seenKeys.has(nk)) continue;
    seenKeys.add(nk);
    const op = issue.operative || 'Unknown operative';
    if (!groupsByOperative.has(op)) groupsByOperative.set(op, []);
    groupsByOperative.get(op).push(issue);
  }
  return [...groupsByOperative.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([operative, forms]) => ({ operative, issue_count: forms.length, forms }));
}

const reportDate = todayUkDate();
const lookback = daysToLookBack();
const scope = scopeDateSet();

const existingOpenKeys = new Set(
  existingRows()
    .filter(row => normalize(row.status || row.Status) === 'open')
    .map(row => normalize(row.issue_key || row['Issue Key']))
    .filter(Boolean),
);

const newIssues = [];
const diagnostics = {
  incorrect_forms_in_report: 0,
  missing_photos_in_report: 0,
  candidate_issues: 0,
  skipped_date_scope: 0,
  skipped_existing_open: 0,
  existing_open_in_pdf: 0,
  scope_dates: scope ? [...scope].sort() : ['all'],
  days_to_look_back: lookback === null ? 'all' : lookback,
  existing_open_keys: existingOpenKeys.size,
};

function addIssue(row, issueType, issueDetail) {
  diagnostics.candidate_issues += 1;
  const dateCreated = rowDateCreated(row) || clean(row.form_date);
  if (!dateInScope(dateCreated)) {
    diagnostics.skipped_date_scope += 1;
    return;
  }

  const key = issueKey({ ...row, date_created: dateCreated }, issueType);
  if (!key || existingOpenKeys.has(normalize(key))) {
    diagnostics.skipped_existing_open += 1;
    return;
  }

  newIssues.push({
    issue_key: key,
    status: 'Open',
    first_detected_date: reportDate,
    last_seen_date: reportDate,
    resolved_date: '',
    operative: clean(row.operative) || 'Unknown operative',
    corf: clean(row.corf),
    smart_form_x_id: clean(row.smart_form_x_id),
    form_date: clean(row.form_date),
    date_created: dateCreated,
    smart_form_name: clean(row.smart_form_name),
    issue_type: issueType,
    issue_detail: issueDetail,
    issue_summary: clean(row.issue_summary || row.reason || issueDetail),
    issue_resolved: '',
    pdf_url: clean(row.pdf_url),
    access_issue: row.access_issue === true,
    access_issue_reason: clean(row.access_issue_reason),
    is_new: true,
  });
}

const report = $('Build Daily Exception Report').first().json;
diagnostics.incorrect_forms_in_report = (report.incorrect_forms || []).length;
diagnostics.missing_photos_in_report = (report.missing_photos || []).length;
diagnostics.next_appointments_in_report = (report.next_appointments || []).length;
diagnostics.operative_rows_in_scope = report.operative_rows_in_scope ?? report.summary?.operative_rows_in_scope ?? 0;
diagnostics.total_exception_count = report.total_exception_count ?? 0;
diagnostics.form_issue_cases_source = 'incorrect_forms and missing_photos only (not next_appointments)';

for (const row of report.incorrect_forms || []) {
  const detail = combineIssues(row.issues, row.issue_summary || 'Incorrectly completed form');
  addIssue({ ...row, issue_summary: detail }, 'Incorrect form', detail);
}
for (const row of report.missing_photos || []) {
  const detail = combineIssues(row.issues, row.issue_summary || 'Required photos missing');
  addIssue({ ...row, issue_summary: detail }, 'Missing photos', detail);
}

const newIssueKeys = new Set(newIssues.map(i => normalize(i.issue_key)).filter(Boolean));
const existingOpenForPdf = [];
for (const row of existingRows()) {
  if (normalize(row.status || row.Status) !== 'open') continue;
  const mapped = sheetRowToIssue(row);
  if (!mapped.issue_key) continue;
  if (newIssueKeys.has(normalize(mapped.issue_key))) continue;
  existingOpenForPdf.push(mapped);
}
diagnostics.existing_open_in_pdf = existingOpenForPdf.length;

const pdfIssues = [...newIssues, ...existingOpenForPdf];
const operative_groups = buildOperativeGroups(pdfIssues);

const uniqueForms = new Set(
  pdfIssues.map(i => i.smart_form_x_id || `${i.corf}:${i.date_created || i.form_date}`)
);
const accessForms = new Set(
  pdfIssues.filter(i => i.access_issue).map(i => i.smart_form_x_id || `${i.corf}:${i.date_created || i.form_date}`)
);
const dateSlug = new Date().toISOString().slice(0, 10);

return [{
  json: {
    report_type: 'daily_form_report',
    report_generated_at: new Date().toISOString(),
    report_date: reportDate,
    days_to_look_back: lookback === null ? 'all' : lookback,
    scope_dates: scope ? [...scope].sort() : ['all'],
    diagnostics,
    summary: {
      new_issue_count: newIssues.length,
      existing_open_count: existingOpenForPdf.length,
      total_issue_count: pdfIssues.length,
      affected_operatives: operative_groups.length,
      affected_forms: uniqueForms.size,
      access_issue_forms: accessForms.size,
    },
    new_issue_cases: newIssues,
    operative_groups,
    pdf_filename: `daily-form-report-${dateSlug}.pdf`,
  },
}];

const payload = $('Build Daily Form Issue Cases').first().json || {};
const cases = Array.isArray(payload.new_issue_cases) ? payload.new_issue_cases : [];
const diag = payload.diagnostics || {};

if (!cases.length) {
  const parts = [];
  const formIssues = (diag.incorrect_forms_in_report || 0) + (diag.missing_photos_in_report || 0);
  const nextAppts = diag.next_appointments_in_report || 0;
  if (formIssues === 0) {
    if (nextAppts > 0) {
      parts.push(`${nextAppts} incomplete jobs in daily report are next-appointment exceptions only; Form Issue Cases tracks Incorrect form and Missing photos, not incomplete job status`);
    } else {
      parts.push('No validation issues found in scoped OJS rows');
    }
  }
  if (diag.skipped_existing_open) {
    parts.push(`${diag.skipped_existing_open} already Open on Form Issue Cases sheet`);
  }
  if (diag.skipped_date_scope) {
    parts.push(`${diag.skipped_date_scope} outside date scope (${(diag.scope_dates || []).join(', ')})`);
  }
  return [{
    json: {
      _skip_append: true,
      reason: parts.length ? parts.join('; ') : 'No new issue cases in scope',
      new_issue_count: 0,
      diagnostics: diag,
    },
  }];
}

return cases.map((issue, index) => ({
  json: issue,
  pairedItem: { item: 0, input: 0 },
}));

const TZ = 'Europe/London';
const DATE_COL = 'Date Created';

function clean(value) {
  return value === null || value === undefined ? '' : String(value).trim();
}

function extractFirstDate(value) {
  return clean(value).match(/\d{2}\/\d{2}\/\d{4}/)?.[0] || '';
}

function londonTodayParts() {
  const fmt = new Intl.DateTimeFormat('en-GB', {
    timeZone: TZ,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  });
  const bits = fmt.formatToParts(new Date());
  const out = {};
  for (const bit of bits) {
    if (bit.type !== 'literal') out[bit.type] = bit.value;
  }
  return { y: +out.year, m: +out.month, d: +out.day };
}

function formatParts(parts) {
  const pad = n => (n < 10 ? '0' + n : String(n));
  return `${pad(parts.d)}/${pad(parts.m)}/${parts.y}`;
}

function addDays(parts, delta) {
  const dt = new Date(Date.UTC(parts.y, parts.m - 1, parts.d));
  dt.setUTCDate(dt.getUTCDate() + delta);
  return { y: dt.getUTCFullYear(), m: dt.getUTCMonth() + 1, d: dt.getUTCDate() };
}

function todayUkDate() {
  return formatParts(londonTodayParts());
}

function readParams() {
  try {
    return $('Set Daily PDF API Params').first().json || {};
  } catch {
    return {};
  }
}

function daysToLookBack() {
  const params = readParams();
  if (params.backfill_all_dates === true) return null;
  const raw = params.days_to_look_back;
  const n = Number(raw);
  if (!Number.isFinite(n) || n < 0) return 0;
  return Math.floor(n);
}

function scopeDateSet() {
  const lookback = daysToLookBack();
  if (lookback === null) return null;
  const dates = new Set();
  const end = londonTodayParts();
  for (let i = 0; i <= lookback; i++) {
    dates.add(formatParts(addDays(end, -i)));
  }
  return dates;
}

const FORM_DATE_COL = 'Q1.2 Date';

function rowDateCreated(row) {
  return (
    extractFirstDate(row[DATE_COL] || row.date_created) ||
    extractFirstDate(row[FORM_DATE_COL] || row.form_date)
  );
}

function dateInScope(dateCreated) {
  const scope = scopeDateSet();
  if (!scope) return true;
  return scope.has(dateCreated);
}

const lookback = daysToLookBack();
const scope = scopeDateSet();
const scopeLabel = scope ? [...scope].sort().join(', ') : 'all dates';
const inputCount = $input.all().length;

if (lookback === null) {
  return $input.all().map((item, index) => ({
    json: { ...(item.json || {}), _date_created_scope: 'backfill' },
    pairedItem: { item: index },
  }));
}

const kept = [];
let skipped = 0;

for (const item of $input.all()) {
  const row = item.json || {};
  const dateCreated = rowDateCreated(row);
  if (!dateInScope(dateCreated)) {
    skipped += 1;
    continue;
  }
  kept.push({
    json: { ...row, _date_created_scope: scopeLabel },
    pairedItem: item.pairedItem,
  });
}

if (kept.length === 0) {
  return [{
    json: {
      _no_rows_in_scope: true,
      _date_created_scope: scopeLabel,
      _filter_summary: {
        input_rows: inputCount,
        kept_rows: 0,
        skipped_rows: skipped,
        days_to_look_back: lookback,
      },
    },
  }];
}

return kept.map((item, index) => ({
  ...item,
  json: {
    ...item.json,
    _filter_summary: index === 0 ? {
      input_rows: inputCount,
      kept_rows: kept.length,
      skipped_rows: skipped,
      days_to_look_back: lookback,
      scope_dates: scopeLabel,
    } : item.json._filter_summary,
  },
}));

const NOTES_FIELD = 'Q3.1 Notes, if applicable';
const COMPLETED_FIELD = 'Q2.2 Were you able to complete your work in full?';

function clean(value) {
  return value === null || value === undefined ? '' : String(value).trim();
}
function norm(value) { return clean(value).toLowerCase(); }
function isTruthyFlag(value) {
  return ['true','yes','1','access issue','access issue detected'].includes(norm(value));
}
function notesArePlaceholder(notes) {
  const n = norm(notes);
  return n === '' || n === 'not answered' || n === 'none' || n === 'n/a';
}
function hasExplicitAccessColumn(row) {
  const value = row['Access Issue'] ?? row['Access Issue Detected'] ?? row['Has Access Issue'] ?? row.access_issue;
  return value !== null && value !== undefined && clean(value) !== '';
}
function notesSuggestAccessReview(notes) {
  const n = norm(notes);
  if (notesArePlaceholder(notes)) return false;
  const keywords = ['access','door','key','keys','refus','not home','no one home','nobody','no answer',"couldn't enter",'could not enter','unable to enter','occupant','tenant','resident','locked','entry','appointment','let in','let us in','gain access','no access'];
  return keywords.some(k => n.includes(k));
}
function needsAccessAi(row) {
  if (row._no_rows_in_scope) return false;
  if (hasExplicitAccessColumn(row)) return false;
  const notes = row[NOTES_FIELD];
  if (notesArePlaceholder(notes)) return false;
  if (norm(row[COMPLETED_FIELD]) === 'no') return true;
  return notesSuggestAccessReview(notes);
}

const inputItems = $input.all().filter(item => !item.json?._no_rows_in_scope);

return inputItems.map((item, index) => {
  const row = { ...item.json };
  const needsAi = needsAccessAi(row);
  let access_issue = false;
  let access_issue_reason = '';
  if (hasExplicitAccessColumn(row)) {
    access_issue = isTruthyFlag(row['Access Issue'] ?? row.access_issue);
    access_issue_reason = access_issue ? clean(row['Access Issue Reason'] ?? row.access_issue_reason) : '';
  }
  return {
    json: {
      ...row,
      _ojs_index: index,
      _needs_access_ai: needsAi,
      access_issue: needsAi ? false : access_issue,
      access_issue_reason: needsAi ? '' : access_issue_reason,
    },
    pairedItem: { item: index },
  };
});

