const prepared = $('Prepare Access Classification').all();
const aiNeeded = prepared.filter(item => item.json._needs_access_ai === true);

let aiItems = [];
if (aiNeeded.length) {
  try {
    aiItems = $('Classify Access Issue (OpenAI)').all();
  } catch {
    aiItems = [];
  }
}

if (aiItems.length !== aiNeeded.length) {
  throw new Error(`OpenAI returned ${aiItems.length} items for ${aiNeeded.length} forms that needed access classification.`);
}

function parseJson(value) {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return null; }
}

function findClassification(value, depth = 0) {
  if (depth > 8 || value === null || value === undefined) return null;
  const parsed = parseJson(value);
  if (parsed !== value) return findClassification(parsed, depth + 1);
  if (typeof value !== 'object') return null;
  if (Object.prototype.hasOwnProperty.call(value, 'access_issue')) {
    return {
      access_issue: value.access_issue === true,
      access_issue_reason: String(value.access_issue_reason ?? '').trim(),
    };
  }
  for (const child of Object.values(value)) {
    const result = findClassification(child, depth + 1);
    if (result) return result;
  }
  return null;
}

const aiByIndex = new Map();
let aiPointer = 0;
for (const item of prepared) {
  if (!item.json._needs_access_ai) continue;
  const classification = findClassification(aiItems[aiPointer]?.json);
  aiPointer += 1;
  if (!classification) {
    throw new Error(`Could not find access classification for smart_form_x_id ${item.json.smart_form_x_id || item.json._ojs_index}.`);
  }
  aiByIndex.set(item.json._ojs_index, classification);
}

return prepared.map(item => {
  const row = { ...item.json };
  const { _ojs_index, _needs_access_ai, ...rest } = row;
  if (_needs_access_ai) {
    const classification = aiByIndex.get(_ojs_index);
    return {
      json: {
        ...rest,
        access_issue: classification.access_issue,
        access_issue_reason: classification.access_issue ? classification.access_issue_reason : '',
      },
      pairedItem: item.pairedItem,
    };
  }
  return { json: rest, pairedItem: item.pairedItem };
});

function clean(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function norm(v) { return clean(v).toLowerCase(); }

let rows = [];
try { rows = $('Read Form Issue Cases').all().map(i => i.json || {}); } catch (e) { rows = []; }

const ids = new Set();
for (const r of rows) {
  if (norm(r.Status || r.status) !== 'open') continue;
  const id = clean(r['SmartForm X ID'] || r.smart_form_x_id);
  if (id) ids.add(id);
}

const smart_form_ids = [...ids];
return [{ json: { smart_form_ids, open_case_count: smart_form_ids.length } }];

function extractApiBody(resp) {
  const statusCode = resp.statusCode ?? resp.status ?? 0;
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) {
      const m = body.match(/\{[\s\S]*\}/);
      if (m) { try { body = JSON.parse(m[0]); } catch (e2) { body = {}; } } else { body = {}; }
    }
  }
  if (body && typeof body === 'object' && body.body && body.results === undefined && body.total_extracted === undefined) {
    body = body.body;
  }
  return { statusCode, body: body || {} };
}

const fetchRaw = $('Fetch Open Cases From EasyBOP').first().json || {};
const { body } = extractApiBody(fetchRaw);
const results = Array.isArray(body.results) ? body.results : [];

let issueCases = [];
try { issueCases = $('Read Form Issue Cases').all().map(i => i.json || {}); } catch (e) { issueCases = []; }

return [{
  json: {
    issue_cases: issueCases,
    extract_results: results,
    refetched_count: results.length,
    open_case_count: issueCases.filter(r => String(r.status || r.Status || '').toLowerCase() === 'open').length,
  },
}];

const r = $input.first().json || {};
const updates = Array.isArray(r.sheet_updates) ? r.sheet_updates : [];
if (!updates.length) {
  return [{
    json: {
      _skip_update: true,
      reason: 'No open cases changed after reconciliation',
      diagnostics: r.diagnostics || {},
    },
  }];
}
return updates.map(u => ({ json: u }));
